import{_ as e,o as d,c as a,a2 as r}from"./chunks/framework.BXzK3EA4.js";const m=JSON.parse('{"title":"후계, 이름 로스터, 세계 원장","description":"","frontmatter":{},"headers":[],"relativePath":"world/Heirs-Names-and-World-Ledger.md","filePath":"world/Heirs-Names-and-World-Ledger.md"}'),o={name:"world/Heirs-Names-and-World-Ledger.md"};function l(n,t,i,h,c,s){return d(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="후계-이름-로스터-세계-원장" tabindex="-1">후계, 이름 로스터, 세계 원장 <a class="header-anchor" href="#후계-이름-로스터-세계-원장" aria-label="Permalink to &quot;후계, 이름 로스터, 세계 원장&quot;">​</a></h1><p>이름 있는 인물이 죽거나 자리를 비우면 빈 직위만 남지 않습니다. 후계자·신임 실무자·새로 붙는 친족은 <a href="/world/Core-Characters.html">작명 원칙</a>을 지키는 성명으로 생성됩니다. 성씨와 이름은 문화 로스터에서 고릅니다. 플레이어의 면담·거래·지지·호송은 인물 단위 기록만 남기고, 그 기록이 임계를 넘을 때 <a href="/rules/Save-and-Determinism.html">사건 원장</a>이 거점·물가·통행·정통성을 바꿉니다.</p><p>이 문서는 생성 규칙입니다. 이미 이름 붙은 412명 캐스트를 다시 짓지 않습니다.</p><h2 id="문화-키" tabindex="-1">문화 키 <a class="header-anchor" href="#문화-키" aria-label="Permalink to &quot;문화 키&quot;">​</a></h2><p>작명 문화는 국가 ID가 아니라 권역 키입니다. 국가가 병합되거나 국호가 바뀌어도 키는 남습니다.</p><table tabindex="0"><thead><tr><th>키</th><th>권역</th><th>쓰는 국가(개막)</th></tr></thead><tbody><tr><td><code>west-sluice</code></td><td>서부 수문</td><td>여의신정수문정부, 서남제작동맹, 마곡연구평의회, 상암송신공사</td></tr><tr><td><code>center-record</code></td><td>중앙 기록·철도</td><td>도성기록청, 용산철도후국, 노량진남관상회, 뚝도공방연합</td></tr><tr><td><code>north-refuge</code></td><td>북부 피난</td><td>북산피난연맹, 창동차륜방</td></tr><tr><td><code>east-caravan</code></td><td>동부 상단</td><td>암사고덕상수단, 신내망우환승시, 약령의정동맹, 아차구의관문국</td></tr><tr><td><code>southeast-ration</code></td><td>동남 배급</td><td>가락잠실배급국, 수서강남협약도시</td></tr></tbody></table><p>인물의 <code>CultureKey</code>는 출생 권역입니다. 이직해도 성명 풀은 바꾸지 않습니다. 자식은 보호자 쪽 키를 따릅니다. 양자는 입적 국가의 키를 받을 수 있으나 기존 성명은 유지합니다.</p><h2 id="로스터-칸" tabindex="-1">로스터 칸 <a class="header-anchor" href="#로스터-칸" aria-label="Permalink to &quot;로스터 칸&quot;">​</a></h2><p>성, 남성 이름, 여성 이름은 파일을 나눈다. 권역 키는 문화 키 표를 따른다.</p><ul><li><a href="name-pools/surnames.json">surnames.json</a> — 성. 한 글자</li><li><a href="name-pools/given-male.json">given-male.json</a> — 남성 이름</li><li><a href="name-pools/given-female.json">given-female.json</a> — 여성 이름</li><li><code>given-open</code> — 성별을 가리지 않을 때만. 후계 생성 기본</li><li><a href="name-pools/clans-hangnyeol.json">clans-hangnyeol.json</a> — 본관과 항렬. 명문·장부 집안만. 규칙은 <a href="/world/Hangnyeol-and-Bon-gwan.html">본관과 항렬</a></li></ul><p>완성 성명은 <code>성 + 이름</code>입니다. 띄어 쓰지 않습니다. 항렬이 켜지면 이름 앞글자를 세대 항렬자로 덮어쓴다. 왕·명문을 자처하는 인물은 외자 이름을 쓸 수 있으나 로스터에 외자가 있을 때만 가능합니다. 로마자, 일본식 자, 실존 정치인 성명은 넣지 않습니다.</p><p>개막 풀은 권역당 성 12개, 통용 이름 24개, 성별 칸 각 8개를 넘기지 않습니다. 캠페인 중에 풀을 늘리지 않습니다. 소진되면 같은 키에서 아직 살아 있지 않은 조합만 다시 고릅니다. 조합이 바닥나면 생성을 거부하고 직위는 공석으로 둡니다. 무명 지도자를 채우지 않습니다.</p><h2 id="이름을-고르는-순서" tabindex="-1">이름을 고르는 순서 <a class="header-anchor" href="#이름을-고르는-순서" aria-label="Permalink to &quot;이름을 고르는 순서&quot;">​</a></h2><ol><li>대상의 <code>CultureKey</code>를 읽는다.</li><li>성 칸에서 아직 동일 국가 생존 인물과 겹치지 않는 성을 고른다. 결정 난수는 <a href="/rules/Save-and-Determinism.html">같은 선택이 같은 결과가 되나</a>의 인물 스트림만 사용한다.</li><li>이름 칸에서 같은 방식으로 고른다. 성별이 있으면 남성·여성 풀을 나눈다. 항렬은 <a href="/world/Hangnyeol-and-Bon-gwan.html">본관과 항렬</a>을 따른다. 추가 100명 랜덤 풀은 <a href="/world/Random-Cast-Roster.html">랜덤 추가 로스터</a>.</li><li><code>성+이름</code>이 전 세계 생존·사망 기록과 같으면 3으로 돌아간다. 8번 실패하면 생성을 거부한다.</li><li>새 인물 ID, 성명, 키, 출생 틱을 원장에 쓴다.</li></ol><p>이미 있는 캐스트 성명은 로스터에서 빼지 않습니다. 생성기가 그 성명을 다시 뽑으면 4번에서 걸러집니다.</p><h2 id="후계가-생기는-때" tabindex="-1">후계가 생기는 때 <a class="header-anchor" href="#후계가-생기는-때" aria-label="Permalink to &quot;후계가 생기는 때&quot;">​</a></h2><p><a href="/world/Ambitions-and-Relations.html">야망과 관계가 움직이는 정치</a>의 계승 순서는 그대로입니다. 지정 후계, 대행자, 추대, 친족·양자, 사제·도제, 길드 추천, 거점 통제.</p><p>바뀌는 점은 하나입니다. 순서를 따라갔는데 이름 있는 후보가 없고, 그 직위가 이름 있는 인물을 요구하면, 위 로스터로 후계 후보를 한 명 생성합니다. 생성 실패 시 직위는 공석입니다. 대행자·관리인만으로 버틸 수 있는 자리는 생성하지 않습니다.</p><p>생성되는 인물은 다음을 갖습니다.</p><ul><li>성명과 <code>CultureKey</code></li><li>보호자 또는 추천자와의 관계 한 줄(양자, 도제, 길드, 친족 중 하나)</li><li>야망·공포는 보호자 직능에서 복사하지 않고, 국가 핵심 인물 표의 빈 칸 규칙을 따릅니다. 표가 없으면 생업만 적습니다.</li></ul><p>플레이어가 후계를 지명하면 로스터를 건너뛰고 그 인물을 씁니다. 지명 대상이 다른 문화 키여도 성명은 바꾸지 않습니다.</p><h2 id="미시-기록" tabindex="-1">미시 기록 <a class="header-anchor" href="#미시-기록" aria-label="Permalink to &quot;미시 기록&quot;">​</a></h2><p>플레이어가 인물에게 하는 일은 국가 수치를 바로 건드리지 않습니다. 아래만 기록합니다.</p><table tabindex="0"><thead><tr><th>행위</th><th>기록 종류</th><th>대상</th></tr></thead><tbody><tr><td>면담</td><td><code>talk</code></td><td>인물</td></tr><tr><td>물자·통행·포로·기록 거래</td><td><code>trade</code></td><td>인물 또는 직위</td></tr><tr><td>후계 공개 지지·실격</td><td><code>heir-stance</code></td><td>후보</td></tr><tr><td>조약 호송</td><td><code>escort</code></td><td>서명자</td></tr><tr><td>소문 반증·폭로</td><td><code>rumour</code></td><td>인물 또는 직위</td></tr><tr><td>쿠데타 지원·경고</td><td><code>plot</code></td><td>주도자</td></tr></tbody></table><p>한 줄에는 원인 ID, 세계 시간, 주체, 대상, 크기, 규칙 판본이 들어갑니다. 크기는 정수입니다. 신뢰·정통성 슬라이더를 직접 올리는 명령은 없습니다.</p><h2 id="거시로-넘어가는-때" tabindex="-1">거시로 넘어가는 때 <a class="header-anchor" href="#거시로-넘어가는-때" aria-label="Permalink to &quot;거시로 넘어가는 때&quot;">​</a></h2><p>원장을 시간순으로 읽어 합이 임계를 넘으면 세계 사건을 한 번만 발행합니다. 같은 원인 ID로 두 번 발행하지 않습니다.</p><table tabindex="0"><thead><tr><th>합산</th><th>임계를 넘기면</th></tr></thead><tbody><tr><td>한 인물에 대한 <code>talk</code>+<code>trade</code></td><td>그 인물의 제안 수락 범위가 넓어지거나 좁아진다</td></tr><tr><td>한 직위 계승 쟁점의 <code>heir-stance</code></td><td>지정 후계가 바뀌거나 계승 전쟁이 열린다</td></tr><tr><td>한 거점의 <code>trade</code> 거절이 쌓임</td><td>통행 허가 철회, 물가 인상</td></tr><tr><td>한 국가의 <code>plot</code> 성공</td><td>수장 교체. 후계 생성 규칙을 탄다</td></tr><tr><td>여러 국가에 걸친 <code>rumour</code> 확정</td><td>정통성 하락, 협약 재검토</td></tr></tbody></table><p>세계 사건은 <a href="/world/Factions-and-Diplomacy.html">세력과 외교</a>, <a href="/world/Economy-and-Production.html">경제와 생산</a>, <a href="/world/Logistics-and-Infrastructure.html">물류와 기반 시설</a>이 읽는 필드만 바꿉니다. 전투 격자나 카드 재충전은 건드리지 않습니다. 전투 결과는 <a href="/rules/Strategy-Battle-Roundtrip.html">전략에서 전투로</a>가 한 번만 반영합니다.</p><h2 id="저장" tabindex="-1">저장 <a class="header-anchor" href="#저장" aria-label="Permalink to &quot;저장&quot;">​</a></h2><p>성명 로스터의 남은 칸, 이미 쓴 성명, 미시 기록, 아직 안 터진 임계는 저장 파일의 세계 상태에 들어갑니다. 인물 스트림 난수는 전투·조우 스트림과 섞지 않습니다.</p><p>지원하지 않는 저장은 이름을 새로 뽑으며 복구하지 않습니다. 오류를 내고 이전 파일을 둡니다.</p>',32)])])}const u=e(o,[["render",l]]);export{m as __pageData,u as default};
